import{_ as d,C as e,o as a,c as n,a6 as o,j as t,a as c,E as r,w as i}from"./chunks/framework.BrkgobfX.js";const P=JSON.parse('{"title":"MCP","description":"从 Bit 到 AGI · 第十二章 · Model Context Protocol——工具与数据源的 USB-C，以及生态现状","frontmatter":{"title":"MCP","description":"从 Bit 到 AGI · 第十二章 · Model Context Protocol——工具与数据源的 USB-C，以及生态现状","source":"https://daiw.org/manual/bit-to-agi/12-future/mcp-future"},"headers":[],"relativePath":"manual/llm/bit-to-agi/12-future/mcp-future.md","filePath":"manual/llm/bit-to-agi/12-future/mcp-future.md"}'),h={name:"manual/llm/bit-to-agi/12-future/mcp-future.md"},g={style:{overflow:"visible","min-height":"1px","min-width":"1px","vertical-align":"0"},xmlns:"http://www.w3.org/2000/svg",width:"2.378ex",height:"1.545ex",role:"img",focusable:"false",viewBox:"0 -683 1051 683","aria-hidden":"true"};function u(m,s,k,b,E,C){const l=e("mjx-assistive-mml"),p=e("mjx-container");return a(),n("div",null,[s[5]||(s[5]=o(`<h1 id="mcp" tabindex="-1">MCP <a class="header-anchor" href="#mcp" aria-label="Permalink to &quot;MCP&quot;">​</a></h1><blockquote><p>从 Bit 到 AGI · 第十二章 · Model Context Protocol——工具与数据源的 USB-C，以及生态现状</p></blockquote><p>每个 SaaS 各写一套 Agent 插件，接口重复、鉴权混乱。<strong>MCP</strong>（Model Context Protocol，Anthropic 2024 开源）试图成为 Agent 与外部世界的<strong>统一插口</strong>：主机（Cursor、Claude Desktop）通过标准 JSON-RPC 连接 MCP Server，暴露 Tools、Resources、Prompts。它是布线标准，不是魔法——连上 MCP 不等于任务能自动完成。</p><h2 id="直觉" tabindex="-1">直觉 <a class="header-anchor" href="#直觉" aria-label="Permalink to &quot;直觉&quot;">​</a></h2><p>USB-C 不提高硬盘速度，但让你<strong>少带一堆线</strong>。MCP 类似：</p><ul><li><strong>MCP Host</strong>：跑 LLM 的应用（IDE、Chat 客户端）</li><li><strong>MCP Client</strong>（在 Host 内）：维护与 Server 的连接</li><li><strong>MCP Server</strong>：封装 GitHub、Postgres、Slack、本地文件等</li></ul><p>换 Host 不必重写 GitHub 集成；换 Server 不必改 Host 的 UI——<strong>若</strong>双方都遵守协议。</p><div class="language-mermaid vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  H[&quot;MCP Host\\n(Cursor / Claude Desktop)&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  C[&quot;MCP Client&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  S1[&quot;Server: filesystem&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  S2[&quot;Server: github&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  S3[&quot;Server: postgres&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  H --&gt; C</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  C --&gt; S1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  C --&gt; S2</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  C --&gt; S3</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><h2 id="定义" tabindex="-1">定义 <a class="header-anchor" href="#定义" aria-label="Permalink to &quot;定义&quot;">​</a></h2><p>MCP 基于 <strong>JSON-RPC 2.0</strong>，常见传输：</p><table tabindex="0"><thead><tr><th>传输</th><th>场景</th></tr></thead><tbody><tr><td><strong>stdio</strong></td><td>本地子进程，Server 以命令行启动</td></tr><tr><td><strong>Streamable HTTP</strong>（及早期 HTTP+SSE）</td><td>远程 Server，支持流式事件与 OAuth 2.1</td></tr></tbody></table><p>三类能力：</p><ol><li><strong>Tools</strong>：可调用函数（类似 function calling）</li><li><strong>Resources</strong>：可读 URI 资源（<code>file://</code>、<code>db://</code> 等）</li><li><strong>Prompts</strong>：预置 prompt 模板</li></ol><p>生命周期：<code>initialize</code> → <code>tools/list</code> → <code>tools/call</code> → （可选）<code>resources/read</code>。</p><p>协议<strong>不规定</strong> LLM 如何用这些能力——推理、规划仍在 Host 的 Agent 逻辑里。</p><h2 id="例子" tabindex="-1">例子 <a class="header-anchor" href="#例子" aria-label="Permalink to &quot;例子&quot;">​</a></h2><p><strong>例 1：stdio Server 配置片段（概念）</strong></p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;mcpServers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;filesystem&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;npx&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;args&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;-y&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;@modelcontextprotocol/server-filesystem&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/Users/me/project&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>Host spawn 子进程，经 stdin/stdout 交换 JSON-RPC。</p><p><strong>例 2：与裸 Tool Use 对比</strong></p><table tabindex="0"><thead><tr><th>维度</th><th>应用内硬编码 Tool</th><th>MCP Server</th></tr></thead><tbody><tr><td>复用 across Host</td><td>否</td><td>是</td></tr><tr><td>进程隔离</td><td>看实现</td><td>stdio 子进程可隔离</td></tr><tr><td>延迟</td><td>低（同进程）</td><td>+进程 IPC <strong>~1–5 ms</strong> 级</td></tr><tr><td>版本管理</td><td>随应用发布</td><td>Server 独立升级</td></tr><tr><td>安全审计</td><td>单点</td><td>需审查每个 Server 权限</td></tr></tbody></table><p><strong>例 3：能力边界</strong></p><ul><li>MCP <strong>不提供</strong> LLM 推理、不提供向量检索算法、不保证 Agent 规划正确</li><li>恶意 Server 可 exfiltrate 文件——<strong>与安装浏览器扩展同级风险</strong></li><li>2026 年生态：官方 + 社区 Server <strong>数百个</strong>，质量参差；无 App Store 级统一审核</li></ul><h2 id="量化" tabindex="-1">量化 <a class="header-anchor" href="#量化" aria-label="Permalink to &quot;量化&quot;">​</a></h2><ul><li><strong>消息开销</strong>：单次 <code>tools/call</code> JSON-RPC 包裹 <strong>~0.5–2 KB</strong>（不含 payload）；大文件应走 Resource 分块，不应塞进 tool 参数</li><li><strong>并发连接</strong>：Host 常支持 <strong>5–20</strong> 个 Server；每 Server 一个进程，内存 <strong>~20–100 MB</strong> 典型</li><li><strong>与第十章关系</strong>：<a href="/Front2Full/manual/llm/bit-to-agi/10-train-your-llm/mcp-integration">第十章 MCP 集成</a> 侧重自建 Server；本章侧重<strong>协议角色</strong>与 Agent 拓扑</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>MCP 标准化「插口」，不标准化「插头质量」。<code>server-filesystem</code> 若挂载 <code>/</code>，一次错误 tool call 仍可能删库——权限 scoped 在 Server 配置层，必须人工收紧。</p></div><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><ol><li><strong>「上了 MCP 就是 Agent 平台」</strong>——只是 IO 层；记忆、规划、eval 仍需自建。</li><li><strong>「MCP 会取代 OpenAI function calling」</strong>——实际是 MCP Server → 适配层 → 各厂商 tool 格式；短期是<strong>并存</strong>。</li><li><strong>「远程 MCP 无延迟」</strong>——跨区 HTTP 加鉴权，单次 call <strong>100 ms–1 s</strong> 很常见，不适合高频 tick 级控制（见 Robotics）。</li></ol><h2 id="动手试一试" tabindex="-1">动手试一试 <a class="header-anchor" href="#动手试一试" aria-label="Permalink to &quot;动手试一试&quot;">​</a></h2><p>阅读任意 MCP Server 的 <code>tools/list</code> 返回，数：</p>`,30)),t("ol",null,[t("li",null,[s[2]||(s[2]=c("工具个数 ",-1)),r(p,{class:"MathJax",jax:"SVG",style:{direction:"ltr",position:"relative"}},{default:i(()=>[(a(),n("svg",g,[...s[0]||(s[0]=[t("g",{stroke:"currentColor",fill:"currentColor","stroke-width":"0",transform:"scale(1,-1)"},[t("g",{"data-mml-node":"math"},[t("g",{"data-mml-node":"mi"},[t("path",{"data-c":"1D440",d:"M289 629Q289 635 232 637Q208 637 201 638T194 648Q194 649 196 659Q197 662 198 666T199 671T201 676T203 679T207 681T212 683T220 683T232 684Q238 684 262 684T307 683Q386 683 398 683T414 678Q415 674 451 396L487 117L510 154Q534 190 574 254T662 394Q837 673 839 675Q840 676 842 678T846 681L852 683H948Q965 683 988 683T1017 684Q1051 684 1051 673Q1051 668 1048 656T1045 643Q1041 637 1008 637Q968 636 957 634T939 623Q936 618 867 340T797 59Q797 55 798 54T805 50T822 48T855 46H886Q892 37 892 35Q892 19 885 5Q880 0 869 0Q864 0 828 1T736 2Q675 2 644 2T609 1Q592 1 592 11Q592 13 594 25Q598 41 602 43T625 46Q652 46 685 49Q699 52 704 61Q706 65 742 207T813 490T848 631L654 322Q458 10 453 5Q451 4 449 3Q444 0 433 0Q418 0 415 7Q413 11 374 317L335 624L267 354Q200 88 200 79Q206 46 272 46H282Q288 41 289 37T286 19Q282 3 278 1Q274 0 267 0Q265 0 255 0T221 1T157 2Q127 2 95 1T58 0Q43 0 39 2T35 11Q35 13 38 25T43 40Q45 46 65 46Q135 46 154 86Q158 92 223 354T289 629Z",style:{"stroke-width":"3"}})])])],-1)])])),r(l,{unselectable:"on",display:"inline",style:{top:"0px",left:"0px",clip:"rect(1px, 1px, 1px, 1px)","-webkit-touch-callout":"none","-webkit-user-select":"none","-khtml-user-select":"none","-moz-user-select":"none","-ms-user-select":"none","user-select":"none",position:"absolute",padding:"1px 0px 0px 0px",border:"0px",display:"block",width:"auto",overflow:"hidden"}},{default:i(()=>[...s[1]||(s[1]=[t("math",{xmlns:"http://www.w3.org/1998/Math/MathML"},[t("mi",null,"M")],-1)])]),_:1})]),_:1})]),s[3]||(s[3]=t("li",null,"各工具 description 的 token 估计（字符数 / 2）",-1)),s[4]||(s[4]=t("li",null,"若全注入 128K 上下文，占窗口百分比",-1))]),s[6]||(s[6]=o('<p>思考：是否需要<strong>动态工具路由</strong>只暴露 Top-5 相关工具。</p><h2 id="深入-鉴权与多租户" tabindex="-1">深入：鉴权与多租户 <a class="header-anchor" href="#深入-鉴权与多租户" aria-label="Permalink to &quot;深入：鉴权与多租户&quot;">​</a></h2><p>MCP Server 常持有 OAuth token（GitHub、Google Drive）。Token 存在 Server 进程内存，Host <strong>不应</strong>把 token 再塞进 LLM 上下文。多用户 SaaS 场景：每个 tenant 独立 spawn Server 实例，或 Server 内按 session 隔离 credential——协议层 2026 仍在演进，<strong>无统一最佳实践</strong>。</p><p>stdio 本地模式下，Server 继承用户 OS 权限——与「运行 <code>curl | bash</code>」同级信任。企业部署应使用 signed Server 包 + 权限 manifest（哪些 path、哪些 env var 可读）。</p><h2 id="与-a2a、openapi-生态" tabindex="-1">与 A2A、OpenAPI 生态 <a class="header-anchor" href="#与-a2a、openapi-生态" aria-label="Permalink to &quot;与 A2A、OpenAPI 生态&quot;">​</a></h2><p>Google <strong>A2A</strong>（Agent-to-Agent）协议关注 Agent 间互操作；MCP 关注 Agent 与<strong>数据/工具</strong>。OpenAPI 描述 REST；MCP Tool 可自动生成自 OpenAPI spec 的 adapter，但 REST 的 pagination、rate limit、429 retry 仍需手写。<strong>三套标准并存</strong>，集成商短期逃不掉 adapter 层。</p><h2 id="调试与可观测性" tabindex="-1">调试与可观测性 <a class="header-anchor" href="#调试与可观测性" aria-label="Permalink to &quot;调试与可观测性&quot;">​</a></h2><p>MCP 消息可 dump 为 JSONL trace，对齐 OpenTelemetry span：<code>tools/list</code> → <code>tools/call</code> → latency breakdown。常见故障：<strong>stdio 缓冲</strong>导致 deadlock（需 line-buffered）、<strong>Streamable HTTP / SSE 断连</strong>未重连、<strong>schema 漂移</strong>（Server 升级而 Host cache 旧 list）。</p><h2 id="自建-mcp-server-最小骨架" tabindex="-1">自建 MCP Server 最小骨架 <a class="header-anchor" href="#自建-mcp-server-最小骨架" aria-label="Permalink to &quot;自建 MCP Server 最小骨架&quot;">​</a></h2><p>Server 需实现 <code>initialize</code>、<code>tools/list</code>、<code>tools/call</code> 三件套。Python 官方 SDK 用 decorator 注册 tool；编译为 stdio 入口供 Host 启动。一个只暴露 <code>ping()</code> 的 Server <strong>~50 行</strong>，是验证 Host 集成的第一步——先于接真实数据库。第十章 <a href="/Front2Full/manual/llm/bit-to-agi/10-train-your-llm/mcp-integration">MCP 集成</a> 会展开训练管线侧用法；本章强调 <strong>运行时拓扑</strong>。</p><p>企业内网部署时，HTTP MCP 需 mTLS + 短生命周期 token；stdio 适合单用户桌面。<strong>不要</strong>把 production DB credential 写进 Server 源码——用环境变量 + secret manager，与 Twelve-Factor 一致。</p><p>Host 与 Server 版本协商在 <code>initialize</code> 完成；major 版本不匹配应 <strong>fail fast</strong> 而非 silent 降级。维护 internal MCP registry（名称、owner、权限 tier、最后安全 audit 日期）是 <strong>50+ Server</strong> 规模时的最低治理——否则无人知道哪个进程能读 payroll 表。</p><p>Cursor、Claude Desktop、VS Code 等 Host 对 MCP 的支持深度不同：有的仅 Tools，有的含 Resources 预览。<strong>移植 Server 前</strong>先在目标 Host 跑通 <code>ping</code> tool，再接入生产数据——避免「本地通、IDE 不通」的集成债务。</p><p>协议仍在快速演进（2024-11 首发后经 2025–2026 多次 revision）；锁死某一 SDK minor 版本并读 changelog，是避免 Host 升级 overnight 挂掉的保守策略。</p><p>Resources 适合 <strong>大文档懒加载</strong>（<code>resources/read</code> 按 URI 分页），Tools 适合 <strong>有副作用</strong> 的操作——混用会导致把 10 MB log 塞进 tool result。读 <a href="/Front2Full/manual/llm/bit-to-agi/12-future/tool-use">Tool 篇</a> 的 payload 预算原则同样适用于 MCP。</p><p>Prompts 类型常被忽视：MCP 可 ship <strong>预置 prompt 模板</strong>（如「code review 检查清单」），Host 一键注入——减少每个应用重复维护 system prompt 的 drift。Prompts 不含 secrets，适合版本管理与 code review。</p><p>当组织内部 MCP Server 超过 <strong>10 个</strong> 时，应指定 <strong>platform team</strong> 维护共享 SDK、鉴权与 audit 标准——否则每个业务线各自 spawn 进程，桌面端会变成权限无法审计的「工具动物园」。</p><p>学习 MCP 高效的方式是 <strong>读一个官方 Server 源码</strong>（filesystem 或 fetch）并 tcpdump stdio 消息——比只读 spec 更快建立 JSON-RPC 直觉与独立排障能力，实操很有用。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>MCP = Agent 生态的<strong>标准化连接协议</strong>（Tools / Resources / Prompts）。降低重复集成成本，不解决模型能力、安全与多步可靠性。下一篇：从 API 调用到<strong>看屏幕、点鼠标</strong>——Computer Use。</p><p>→ 下一篇：<a href="/Front2Full/manual/llm/bit-to-agi/12-future/computer-use">Computer Use</a></p>',21))])}const v=d(h,[["render",u]]);export{P as __pageData,v as default};
